    "lib/editor/editor_wiring.dart":
        "// What the editor needs from the game, made where a hot reload can redo it.\n//\n// A hot reload swaps the code but runs nothing again, so anything main\n// hands the editor from code would stay as it was at launch. The editor\n// calls EditorWiring.wire after every reload instead, and main uses the\n// same functions.\n//\n// Developer-only, like everything under lib/editor/: lib/main.dart never\n// imports it, so none of it ships.\n//\n// ignore_for_file: depend_on_referenced_packages\n\nimport 'package:just_asset_store_editor/just_asset_store_editor.dart';\nimport 'package:just_game_engine/just_game_engine.dart';\nimport 'package:just_game_engine_editor/just_game_engine_editor.dart';\n\nimport '../game/game_boot.dart';\nimport 'store_modules.g.dart';\n\n/// The editor's view of the game, for launch and for every hot reload.\nabstract final class EditorWiring {\n  /// The editor's modules.\n  ///\n  /// AssetStoreModule is the Asset Store (Ctrl+Shift+G), listed by hand\n  /// so a broken generated file can never take it down. storeModules() is\n  /// every module the installed store items bring\n  /// (lib/editor/store_modules.g.dart, rewritten by `just add`). Your own\n  /// game's module goes here too.\n  static List<EditorModule> modules() => [\n    AssetStoreModule(),\n    ...storeModules(),\n  ];\n\n  /// After a hot reload: the extensions, systems, modules and spawners\n  /// again, from the code as it now is.\n  static void wire(Engine engine, JustGameEditorPlugin plugin) {\n    engine.context.installAll(GameBoot.extensions);\n    GameBoot.addMissingSystems(engine);\n    plugin.syncModules(modules());\n    plugin.scope.spawners.value = GameBoot.spawners;\n  }\n}\n",
    "lib/editor/store_modules.g.dart":
        "// GENERATED by the Just Asset Store from just_store.lock.json.\n// Do not edit: install, update or remove items in the Asset Store,\n// or run `just store generate`.\n//\n// ignore_for_file: depend_on_referenced_packages, directives_ordering\n// ignore_for_file: unused_import\n\nimport 'package:just_game_engine_editor/just_game_engine_editor.dart'\n    show EditorModule;\n\n/// The editor modules of the items installed from the Asset\n/// Store, in the order they register.\nList<EditorModule> storeModules() => [];\n",
    "lib/game/game_app.dart":
        "import 'package:flutter/material.dart';\nimport 'package:just_game_engine/just_game_engine.dart';\n\nimport 'game_boot.dart';\n\n/// The game: the engine, the first level in assets/scenes/scenes.json, and\n/// what its spawn points create.\n///\n/// Shared by both entry points: lib/main.dart shows it alone, and\n/// lib/main_editor.dart boots the same world for the editor.\nclass GameApp extends StatefulWidget {\n  const GameApp({super.key});\n\n  @override\n  State<GameApp> createState() => _GameAppState();\n}\n\nclass _GameAppState extends State<GameApp> {\n  Engine? _engine;\n\n  @override\n  void initState() {\n    super.initState();\n    _boot();\n  }\n\n  Future<void> _boot() async {\n    final engine = await GameBoot.boot();\n    // The level is the JSON the editor saved, loaded through the engine.\n    final first = (await SceneLoader.loadManifest()).first;\n    await SceneLoader.loadAsset(engine.world, SceneAssets.pathFor(first));\n    await LevelMaps.preload(engine.world);\n    SpawnPoints.spawnAll(engine.world, GameBoot.spawners);\n    engine.start();\n    if (!mounted) {\n      await engine.dispose();\n      return;\n    }\n    setState(() => _engine = engine);\n  }\n\n  @override\n  void dispose() {\n    _engine?.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final engine = _engine;\n    if (engine == null) {\n      return const Center(child: CircularProgressIndicator());\n    }\n    return GameWidget(engine: engine);\n  }\n}\n",
    "lib/game/game_boot.dart":
        "import 'package:flutter/painting.dart';\nimport 'package:just_game_engine/just_game_engine.dart';\n\nimport 'store_extensions.g.dart';\n\n/// Brings up the engine: shared by the game and the editor, so both run the\n/// same world.\nabstract final class GameBoot {\n  /// Makes and initialises an engine with the game's systems. Each call\n  /// makes a new one; the caller disposes it.\n  static Future<Engine> boot() async {\n    final engine = Engine(config: config);\n    await engine.initialize();\n    registerSystems(engine);\n    return engine;\n  }\n\n  /// What the game teaches its engine: the components a level can hold.\n  /// [storeExtensions] is what the installed store items add (generated in\n  /// lib/game/store_extensions.g.dart); the game's own go after it.\n  static const extensions = <ContextExtension>[\n    ...storeExtensions,\n  ];\n\n  /// The engine's standard systems — input, physics, movement, audio,\n  /// rendering, sprites, level maps, cameras — and [extensions].\n  static const config = EngineConfig(\n    extensions: extensions,\n    defaultSystems: DefaultSystems.all,\n  );\n\n  /// The game's own systems, added to the standard ones.\n  static List<System> systems(Engine engine) => [];\n\n  /// Adds [systems] to [engine]'s world.\n  static void registerSystems(Engine engine) =>\n      systems(engine).forEach(engine.world.addSystem);\n\n  /// Adds the [systems] the world doesn't have yet: after a hot reload, a\n  /// new system runs without a restart.\n  static void addMissingSystems(Engine engine) {\n    final running = {for (final s in engine.world.systems) s.runtimeType};\n    for (final system in systems(engine)) {\n      if (!running.contains(system.runtimeType)) {\n        engine.world.addSystem(system);\n      }\n    }\n  }\n\n  /// What a level's spawn points can create. The editor's Play button and\n  /// the game spawn through these, so play-testing makes what ships.\n  static List<Spawner> get spawners => [\n    Spawner(\n      id: 'player',\n      label: 'Player',\n      description: 'The player starts here.',\n      tags: const {'player'},\n      spawn: (world, point) {\n        final at = point.getComponent<TransformComponent>()?.position;\n        return world.createEntityWithComponents([\n          TransformComponent(position: Vector3(at?.x ?? 0, at?.y ?? 0, 0)),\n          // A placeholder to see: swap in your sprite and controls.\n          RectangleComponent(\n            width: 32,\n            height: 48,\n            fillStyle: const ShapePaintStyle(color: Color(0xFF6C8CFF)),\n          ),\n          // The level's camera follows whatever is tagged 'player'.\n          TagComponent('player'),\n        ], name: 'Player');\n      },\n    ),\n  ];\n}\n",
