        "// GENERATED by the Just Asset Store from just_store.lock.json.\n// Do not edit: install, update or remove items in the Asset Store,\n// or run `just store generate`.\n//\n// ignore_for_file: depend_on_referenced_packages, directives_ordering\n// ignore_for_file: unused_import\n\nimport 'package:just_game_engine/just_game_engine.dart'\n    show ContextExtension;\n\n/// What the items installed from the Asset Store teach the\n/// engine: their components, field types and the rest. Spread\n/// it into the game's EngineConfig extensions.\nconst List<ContextExtension> storeExtensions = [];\n",
    "lib/main.dart":
        "// {{title}} — the game, as it ships.\n//\n// Deliberately does NOT import the editor: keeping it out of this file's\n// imports is what keeps it out of a release build (`just check` proves it).\n// To author levels, run the editor instead:\n//\n//     just game run --editor\n\nimport 'package:flutter/material.dart';\n\nimport 'game/game_app.dart';\n\nvoid main() {\n  WidgetsFlutterBinding.ensureInitialized();\n  runApp(const {{App}}());\n}\n\n/// The application.\nclass {{App}} extends StatelessWidget {\n  const {{App}}({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return const MaterialApp(\n      title: '{{title.dart}}',\n      debugShowCheckedModeBanner: false,\n      home: Scaffold(backgroundColor: Color(0xFF1A1A2E), body: GameApp()),\n    );\n  }\n}\n",
    "lib/main_editor.dart":
        "// {{title}} — the game with the editor over it.\n//\n//     just game run --editor\n//\n// Desktop only: the editor saves scenes into assets/scenes/ through\n// dart:io, so it runs from the project folder on Windows, macOS or Linux.\n//\n// The editor never ships. In a profile or release build of this file, main\n// runs the game exactly as lib/main.dart does, and the compiler drops the\n// editor as dead code. Hot reload (r) reaches the editor's modules, the\n// game's components and spawners: lib/editor/editor_wiring.dart is what the\n// editor runs again after each reload.\n\n// The editor packages are dev dependencies; only this entry point imports\n// them.\n// ignore_for_file: depend_on_referenced_packages\n\nimport 'package:flutter/foundation.dart' show kDebugMode;\nimport 'package:flutter/material.dart';\nimport 'package:just_game_engine/just_game_engine.dart';\nimport 'package:just_game_engine_editor/just_game_engine_editor.dart';\n\nimport 'editor/editor_wiring.dart';\nimport 'game/game_boot.dart';\nimport 'main.dart' show {{App}};\n\nFuture<void> main() async {\n  WidgetsFlutterBinding.ensureInitialized();\n\n  // kDebugMode is a compile-time constant, so a release build keeps only\n  // the game's branch and _runEditor is not compiled in. An early `return`\n  // would not do: code after it still is. `just doctor` checks that main\n  // keeps this shape.\n  if (kDebugMode) {\n    await _runEditor();\n  } else {\n    runApp(const {{App}}());\n  }\n}\n\n/// The editor over the game: debug builds only.\nFuture<void> _runEditor() async {\n  if (!JustGameEditorPlugin.supportsPlatform) {\n    // A phone, a tablet or the web: nothing on disk to edit. Play instead.\n    runApp(const {{App}}());\n    return;\n  }\n\n  // The same boot the game uses, so the editor edits the world it runs.\n  final engine = await GameBoot.boot();\n  final plugin = await JustGameEditorPlugin.register(\n    engine: engine,\n    // The Asset Store, and every module the installed store items bring.\n    modules: EditorWiring.modules(),\n    // Play ▶ spawns at each spawn point through these.\n    spawners: GameBoot.spawners,\n    onReassemble: (plugin) => EditorWiring.wire(engine, plugin),\n  );\n  engine.start();\n  runApp(_EditorApp(engine: engine, plugin: plugin));\n}\n\nclass _EditorApp extends StatelessWidget {\n  const _EditorApp({required this.engine, required this.plugin});\n\n  final Engine engine;\n  final JustGameEditorPlugin? plugin;\n\n  @override\n  Widget build(BuildContext context) {\n    return MaterialApp(\n      title: '{{title.dart}} — Editor',\n      debugShowCheckedModeBanner: false,\n      home: Scaffold(\n        backgroundColor: const Color(0xFF1A1A2E),\n        body: JustGameEngineEditor(\n          engine: engine,\n          plugin: plugin,\n          showTerminal: true,\n        ),\n      ),\n    );\n  }\n}\n",
